const MONEY_PATCH = [
  '@@ -0,0 +1,11 @@',
  '+export function formatMoney(amount: number | null): string {',
  "+  if (amount === null) return '—'",
  "+  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(amount)",
  '+}',
  '+',
  '+export function breakdownLabel(breakdown: DiscountBreakdown): string {',
  '+  return [',
  '+    `Code ${formatMoney(breakdown.codeTotal)}`,',
  '+    `Shipping ${formatMoney(breakdown.shippingTotal)}`,',
  "+  ].join(' · ')",
  '+}',
].join('\n');

